// One output file a Provider guest emitted: its on-disk path relative to the node's output root, and its serialized bytes exactly as the guest produced them. The host writes these bytes verbatim and runs no serializer, so the on-disk output is byte-identical to what the guest emitted.
export interface RenderedFile {
  // The output file's path relative to the node's output root (for example Chart.yaml or templates/deployment.yaml).
  path: string;
  // The file's serialized bytes exactly as the guest produced them; the host writes these bytes verbatim and runs no serializer, so output is byte-identical to what the guest emitted. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
  content: string;
  // The format the guest declares the emitted file was rendered in, so the host can route the file to a matching parser. Absent when the guest declares no format, in which case the host infers the format from the file extension.
  format?: string;
}

// One fact a Provider guest reports about what it emitted for a node: a name and a list of entries, both defined and documented by the provider. The host carries the fact as the guest wrote it, refuses one whose value is not a list, and learns nothing else about either half.
export interface RenderFact {
  // The fact's name, from the provider's own documented vocabulary.
  name: string;
  // The fact's value: a JSON array — always a list, even with one entry or none — whose entries are any JSON values in the shape the provider documents for that name. A list is what lets one name be reported by more than one render of a node: the host joins the lists into one. It is carried as the JSON document the guest wrote, byte for byte, so the order of the list's entries and of each object's keys is the guest's own.
  value: unknown;
}

// One entry naming rendered units a Provider guest leaves out of a node's output, its fields already resolved to plain strings and marked where any of them was produced from a value declared sensitive. The socket attaches no meaning to them: each provider documents what kind, name, namespace and subchart select in its own format, and matches them itself.
export interface OmitEntry {
  // The kind of rendered unit the entry names, in the provider's own vocabulary.
  kind: string;
  // The name of the rendered unit the entry names, in the provider's own vocabulary.
  name: string;
  // The namespace the named unit sits in, for a provider whose format places units in one. Absent when the author wrote none; what an entry with no namespace matches is the provider's own contract.
  namespace?: string;
  // The nested source the named unit came from, for a provider whose source is assembled from nested sources, as a chart is from its subcharts. Absent when the author wrote none; what an entry with no subchart matches, and what a provider whose source has no nested sources does with an entry naming one, is the provider's own contract.
  subchart?: string;
  // True when the template that produced any of the entry's kind, name, namespace or subchart reads a value an author declared sensitive, or a value traced to one. It is read from each field's template against the declarations — a reference reaching a declared value, the template handing on the whole of its data, or a template that does not parse all count — and never from the resolved strings. The mark covers the whole entry rather than naming the field, so a guest treats a marked entry as it treats every other marked value on its input: it still matches and counts the entry by its fields, which is what the entry is for, and keeps every field of it out of any text a person reads — a refusal, a warning or a log line. Absent when no field's template reads such a value; absence never states that no field is sensitive.
  sensitive?: boolean;
}

// One file of a pre-packaged source projection: its path relative to the source root and its raw bytes, exactly as the host read them from the local source at compile time.
export interface SourceFile {
  // The file's path relative to the source root (for example Chart.yaml or templates/deployment.yaml).
  path: string;
  // The file's raw bytes exactly as the host read them from the local source. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
  content: string;
}

// The packed source content (e.g. a Helm chart's files, each named by its path relative to the source root, in walk order) the host reads and returns to the guest in response to a pack-source request, so the guest reconstructs the selected source in memory and touches no filesystem. It is the pack-source host function's success payload.
export interface SourceProjection {
  // The source files, each named by its path relative to the source root, in the host's deterministic walk order.
  files: SourceFile[];
}

// One entry of a source listing: its path relative to the source root, and whether it is a directory. The host lists names only and reads no content, so an entry carries no bytes.
export interface SourceEntry {
  // The entry's path relative to the source root, slash-separated (for example Chart.yaml or templates/deployment.yaml).
  path: string;
  // Whether the entry is a directory. A guest that resolves a chart root or a single source file among the listing reads this to distinguish directories from files without touching the filesystem.
  is_dir: boolean;
}

// The generic enumeration of an acquired source the host hands a sourced provider guest: the source root, whether that root is a directory, and the sorted root-relative entries under it. The host walks the acquired source with no domain knowledge and reads no file content — it lists names only. The guest applies its own resolution logic over the listing (locating a chart root, selecting a single compose document, vendoring a module tree) and asks the host to pack a chosen selection through the pack-source host function. Entries are sorted by path so the listing is byte-identical across runs of identical input.
export interface SourceListing {
  // The acquired source location the host enumerated. The guest carries it into its own diagnostics when it cannot resolve the source, so a resolution halt names the source the author supplied.
  root: string;
  // Whether the acquired source root is a directory. False for a single-file source (a lone compose document, a single module file, an archive), in which case entries is empty and the guest packs the root itself.
  root_is_dir?: boolean;
  // The root-relative entries under a directory source root, sorted by path. Empty for a single-file source root.
  entries: SourceEntry[];
}

// The selection a guest asks the host to pack from the acquired source through the pack-source host function. The op names the shape of the selection and the path names it relative to the source root; the host resolves the path under the source root, rejecting any escape above it, and returns the packed bytes as a SourceProjection.
export interface SourcePackRequest {
  // The selection shape: file packs the single file at path; dir packs the immediate files of the directory at path; tree packs the whole subtree rooted at path, recursively, in the host's deterministic walk order.
  op: string;
  // The selection location relative to the source root, slash-separated. The empty string (or ".") names the source root itself, so a single-file source is packed with an empty path.
  path: string;
}

// The pack-source host function's reply: on success the packed source, on failure an error message. Exactly one of the two fields is populated. Failure is delivered in-band rather than by trapping, so a guest carries a sandbox rejection or a read failure into its own diagnostics as a deterministic render failure.
export interface SourcePackResponse {
  // The packed source on success; absent on failure.
  source_projection?: SourceProjection;
  // The failure message on failure, naming the selection and the reason; absent on success.
  error?: string;
  // The machine-matchable failure identity on failure, drawn from the closed host-function error-code catalog, set beside the human error message; absent on success. That catalog is a fixed vocabulary naming the ways a host function can fail, and it is a different vocabulary from the halting conditions the compiler registers, whose identifiers a guest reports on a socket output as condition_code and condition_short_code — the key name says which of the two a value belongs to, so the two are never read as one set. A guest branches on this code without parsing the message, tolerating an absent code (older host) or an unrecognized one (newer host) by falling back to the message.
  hostfunc_error_code?: string;
}

// The single-file content read a guest asks the host to perform through the read-source-file host function, for a guest whose resolution logic must inspect a file's content before choosing what to pack. The host resolves the path under the source root, rejecting any escape above it, and returns the file's bytes.
export interface SourceFileRequest {
  // The file location relative to the source root, slash-separated.
  path: string;
}

// The read-source-file host function's reply: on success the file's bytes, on failure an error message. Exactly one of the two fields is populated. Failure is delivered in-band rather than by trapping, so a guest carries a sandbox rejection or a read failure into its own diagnostics as a deterministic render failure.
export interface SourceFileResponse {
  // The file's raw bytes on success; absent on failure. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
  content?: string;
  // The failure message on failure, naming the file and the reason; absent on success.
  error?: string;
  // The machine-matchable failure identity on failure, drawn from the closed host-function error-code catalog, set beside the human error message; absent on success. That catalog is a fixed vocabulary naming the ways a host function can fail, and it is a different vocabulary from the halting conditions the compiler registers, whose identifiers a guest reports on a socket output as condition_code and condition_short_code — the key name says which of the two a value belongs to, so the two are never read as one set. A guest branches on this code without parsing the message, tolerating an absent code (older host) or an unrecognized one (newer host) by falling back to the message.
  hostfunc_error_code?: string;
}

// The fetch-external-input host function's reply: on success the fetched content, on failure an error message and its code. A reply that carries neither failure field is a success, so a zero-length payload is the reply with every field absent. Failure is delivered in-band rather than by trapping, so a guest carries an unresolvable URL or a fetch failure into its own diagnostics as a deterministic render failure. The request is a bare URL string rather than a structured payload, so only the reply has a declared shape.
export interface FetchExternalInputResponse {
  // The fetched payload's raw bytes on success; absent on failure, and absent when the payload is empty. The bytes cross the wire as a byte string, never as base64 text. The Go kit holds them as a byte slice; the Rust and TypeScript kits hold them as a base64 string, which each kit's fetch wrapper decodes, so every wrapper returns the payload's raw bytes.
  content?: string;
  // The failure message on failure, naming the URL and the remedy; absent on success.
  error?: string;
  // The machine-matchable failure identity on failure, drawn from the closed host-function error-code catalog, set beside the human error message; absent on success. That catalog is a fixed vocabulary naming the ways a host function can fail, and it is a different vocabulary from the halting conditions the compiler registers, whose identifiers a guest reports on a socket output as condition_code and condition_short_code — the key name says which of the two a value belongs to, so the two are never read as one set. A guest branches on this code without parsing the message, tolerating an absent code (older host) or an unrecognized one (newer host) by falling back to the message.
  hostfunc_error_code?: string;
}

// The pre-evaluated workload content the host hands a Provider guest so the guest synthesizes provider-native manifests from it in memory, present when the bound Recipe declares a workload rather than a chart source. Determinism is the guest's responsibility: identical input must produce identical bytes.
export interface WorkloadProjection {
  // The host-evaluated, post-validation Workload the guest synthesizes; opaque at this schema layer so the socket schema does not rebind the Workload entity contract.
  workload: unknown;
  // True when the template that produced workload reads a value an author declared sensitive, or a value traced to one. It is read from the template's own references against the declarations — a reference reaching a declared value, the template handing on the whole of its data, or a template that does not parse all count — and never from the content of any field. A rendered workload's fields carry no link back to the data its template read, so this marks the whole document: a guest composing text a person reads, a refusal or a warning, keeps every value the workload carries out of that text when this is true, while the document's shape — its keys and where a value sits — stays readable. The attachment entries the node projection's sensitive_rendered_keys names are marked there whether or not this is set. Absent when the template reads no such value; absence never states that no field is sensitive.
  sensitive_workload?: boolean;
  // Every attachment on the node, projected to its resolved provides and keyed by the attachment instance name a workload attachment reference carries; absent when the node carries no attachments. The host copies the strings through without interpreting them, so the guest reads whichever entries of an attachment's provides it needs to resolve a reference to the resource that attachment produced. Whether an attachment handles declared-sensitive material is not repeated here: it travels on the node projection's matching feature entry, which a guest reads by the same instance name.
  attachment_provides?: Record<string, Map<string, string>>;
}

// The pre-evaluated artifact set the host hands a Provider guest to place into the node's output. The host has already resolved each entry's source (inline content or an imported file it read), evaluated it as a Go template against the render context using the guest's declared artifact-template delimiter pair, and computed the build-provenance label and annotation key sets. The guest owns the format decision, the provenance placement, the on-disk path, and the final bytes. Entries preserve author order so the placed output is byte-identical across runs of identical input.
export interface ArtifactsProjection {
  // The artifact entries the guest places, in author order.
  entries: ArtifactProjectionEntry[];
}

// One pre-evaluated artifact entry the host hands a Provider guest to place: its host-resolved output name, its origin, the already-template-evaluated content bytes, whether the template those bytes came from reads a value declared sensitive, and the build-provenance label and annotation key sets the host computed for the node. The guest decides how to place the provenance (splicing it into a manifest's metadata, prepending it as a comment, or emitting a companion file) and where the file lands.
export interface ArtifactProjectionEntry {
  // The host-resolved output name for the entry: the author-declared map key, with a file supplied by a library bundle nested under that key. The guest places the entry at this name or under a provider-specific sub-path derived from it.
  name: string;
  // Whether the entry was authored as inline content or as an imported file. A guest that rejects one form (an umbrella-chart provider rejects inline content) reads this to halt loudly.
  origin: string;
  // The already-template-evaluated content bytes the host produced from the entry's inline content or imported file, evaluated against the render context using the guest's declared artifact-template delimiter pair. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
  content: string;
  // True when the template this entry's content was evaluated from reads a value an author declared sensitive, or a value traced to one. It is read from the template's own references against the declarations, with the delimiter pair the content was evaluated with — a reference reaching a declared value, the template handing on the whole of its data, or a template that does not parse all count — and never from the content itself. The content is that template's output, so nothing in it can be traced back to the datum it came from: a guest composing text a person reads, a refusal or a warning, keeps every part of the content out of that text when this is true, a parser's own message about the content included. It is set per entry, so one entry's template reading such a value says nothing about another's. Absent when the template reads no such value; absence never states that the content is not sensitive.
  sensitive_content?: boolean;
  // The Kubernetes-label-safe build-provenance key set the host computed for the node, keyed by label name. A guest that stamps provenance into a manifest's metadata.labels splices these; a guest whose output is not Kubernetes YAML ignores them.
  labels?: Record<string, string>;
  // The build-provenance key set the host computed for the node that a Kubernetes label cannot represent, keyed by annotation name. A guest that stamps provenance into a manifest's metadata.annotations splices these; a guest whose output is not Kubernetes YAML ignores them.
  annotations?: Record<string, string>;
}

// The payload a Provider guest receives on its assemble_boundary export — the export that merges the per-node render outputs at one dispatch group into a single assembled artifact (an umbrella chart, a merged compose file). It carries the per-node render outputs with their merged annotations and deployment waves, the dispatch-group output path the assembled artifact lands at, the graph's uses edges for per-service dependency inference, and the render-time context. Not every provider declares the export: providers that emit only flat per-node output omit it.
export interface AssembleBoundaryInput {
  // The per-node render outputs that fed this dispatch group, in node order.
  rendered_nodes: RenderedNode[];
  // The render-time context, carried as the bytes of its JSON document. On this export the host sets only yaml_indent, the render-wide indentation width the assembled files are serialized at; the context's other members carry nothing here, because an assembly merges contributors whose annotations and boundaries differ, and each contributor's annotations arrive on its rendered_nodes entry instead.
  context: unknown;
  // The evaluated dispatch-group output path the assembled artifact lands at; a boundary assembler uses it as the boundary-level fallback identity (e.g. the compose network name for a node carrying no namespace annotation).
  boundary_path: string;
  // The graph's directed uses edges, so a boundary assembler can infer per-service ordering/dependencies across the dispatch group's contributors (e.g. compose depends_on).
  edges?: RenderEdge[];
  // The per-sub-chart payload an umbrella-chart assembler consumes to emit one dependency and one values scope per contributor. Each entry carries the sub-chart's identity, per-instance values, and, for a sub-chart vendored from a chart source, the pristine bytes of that chart's Chart.yaml file. Present for umbrella-chart assembly; a flat-merging assembler omits it.
  sub_charts?: SubChart[];
  // The chart name an umbrella-chart assembler uses for the assembled chart when a name is supplied for the dispatch group; empty when the assembler derives the name from the dispatch-group output path.
  chart_name?: string;
  // The top-level aggregate name an umbrella-chart assembler folds into the assembled chart's derived name; empty when no aggregate identity contributes to the name.
  aggregate_name?: string;
}

// One node's render output as it appears in an assemble_boundary input: the node id, its type, its merged annotations, its sync wave, the values the compiler resolved for it where those are the compiler's to supply and whether a values mapping produced them, and the files the render_node export produced for it — carried in the render output's shape, with every member of that shape other than its files left absent.
export interface RenderedNode {
  // The node's absolute id within the topology graph. A contributor that is not one of the graph's nodes — a Feature attached at a boundary rather than at a component — carries the compiler's own dispatch identity for it here instead, which is the same identity the render_node call for that contributor carried; it distinguishes one contributor from another and is not a name any target accepts. What such a contributor derives names from inside the assembled artifact is a separate carry, derived_name_basis.
  id: string;
  // The node's component-type label, carried on this shape — unlike the per-node render projection, which withholds it. Opaque metadata rather than a behavior switch: it is here so an assembler can group and label the nodes it merges, not so a guest can branch on it.
  type: string;
  // The identity this contributor derives its own names from inside the assembled artifact — a logical id an assembler mints for one of the contributor's published entries, a per-contributor scope in a merged document, the name of a child unit placed at a position of its own. Empty means the id is used directly, which is the value for an ordinary component. A contributor whose id is a dispatch identity a target's name alphabet refuses carries this explicitly, so the assembled artifact addresses its content by a name the target accepts, and two contributors an author can tell apart cannot arrive under one. Where the contributor's content is folded into a document the assembler merges, this is the same carry the render_node call for that contributor received, and carrying it on both is what keeps the two answers equal: a name the contributor declared while rendering and the name the merged document addresses that content by are derived from one identity rather than from two that happen to agree. Where the contributor is placed at a position of its own instead, this is the identity composed for that contributor — for a Feature attached to a component, its own rather than the host component's its render ran against — so a child unit placed beside its host is addressed apart from it.
  derived_name_basis?: string;
  // The directory this contributor's rendered files sit in, relative to the assembled artifact's own position, carrying no trailing separator. A guest that has to name a contributor's files from inside the assembled artifact — the source path of a module block, an include directive — reads the position from here rather than composing one from the contributor's identity, so the path the assembled artifact points at is the path the files were written to. The two are not always one directory apart: a contributor the host placed inside another contributor's position sits deeper than the contributors placed directly beneath the assembly. Present only where the assembling provider places each contributor under a position of its own; a provider that folds its contributors into one document places no per-contributor directory and receives none.
  output_directory?: string;
  rendered: RenderNodeOutput;
  // The node's merged annotations, so a boundary assembler can attribute per-node placement (e.g. the compose network derived from the aggrega.ai/namespace annotation).
  annotations?: Map<string, string>;
  // The deployment wave this node inherited from its containing boundary (default 0; negative permitted), so a boundary assembler can order the contributors it merges relative to one another. A dispatch group can merge contributors from several boundaries, each carrying its own wave, so the wave travels with every node here rather than once for the whole payload. An assembler whose output shape expresses no ordering ignores it.
  sync_wave?: number;
  // The values the compiler resolved for this node, present only for a node rendered from a source — the render_node call that produced its files carried a source_listing. That is the one case where the files came from elsewhere and the values could not be written into them, so a position outside them has to supply them: a boundary assembler places a present dictionary as that contributor's inputs in the assembled artifact itself, rather than beside the contributor's own files, and where the assembled artifact is the only position the target evaluates, that is the difference between an input the target reads and one it never reaches. A node rendered from a workload_projection or an artifacts_projection resolved these values into the files it produced, so it carries none here and the field is absent: supplying them a second time would offer the assembled artifact inputs that node's own files never declare, which the target is free to reject. Keys arrive in sorted order, not author order, and that sorting is what makes the payload byte-identical across runs of identical input; a guest needing any other ordering imposes it itself. An assembler whose output shape carries no per-contributor inputs ignores the field.
  values?: Map<string, unknown>;
  // True when the values this node carries are the output of its bound Recipe's or FeatureRecipe's valuesMapping (a component's Recipe, an attached Feature's FeatureRecipe), rather than the node's values handed on as the author wrote them — the same mark the render_node call for this node carried on its node projection, carried here beside the values it describes. Absent where no valuesMapping ran, and wherever values is absent. Whether an assembler reads it is that assembler's own contract: one whose render_node binds a mapped node's values to the inputs its source declares can learn from it which names that binding filled, while one that places a node's values as its inputs however they were produced does not read it. It records how the values were produced and is never derived from a key's name or a value's content.
  values_mapped?: boolean;
}

// One directed uses edge of the graph, named by its two node ids: source is the consuming node and target the consumed one. The list carries every uses edge of the graph, so either end may be a node outside this dispatch group.
export interface RenderEdge {
  // The consuming node's id — the source end of a directed uses edge.
  source: string;
  // The consumed node's id — the target end a directed uses edge points at.
  target: string;
}

// One sub-chart contributing to an umbrella chart: its instance identity, the version the umbrella pins, the per-instance values the umbrella scopes under the sub-chart's alias, and, for a sub-chart vendored from a chart source, the pristine bytes of that chart's Chart.yaml file. An umbrella-chart assembler builds the umbrella's dependencies and values file from these pure-data views alone and touches no filesystem.
export interface SubChart {
  // The sub-chart's instance identity within the dispatch group; the umbrella scopes the sub-chart's dependency alias and its values under it, so multiple instances of one source chart stay distinct.
  instance_id: string;
  // The version the umbrella pins for the sub-chart. A sub-chart vendored from a chart source instead draws its dependency name and version from that chart's Chart.yaml file so the dependency binds; this value applies to a generative sub-chart that carries no vendored chart.
  version?: string;
  // The per-instance values the umbrella scopes under the sub-chart's alias in the umbrella values.yaml file. Keys arrive in sorted order, not author order, and that sorting is what makes the payload byte-identical across runs of identical input; a guest needing any other ordering imposes it itself.
  values?: Map<string, unknown>;
  // The pristine bytes of the vendored chart's Chart.yaml, read from the local source at compile time, from which the umbrella draws the sub-chart dependency's name and version. Empty for a generative sub-chart that carries no vendored chart. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
  chart_yaml?: string;
}

// The payload a Provider guest returns from its assemble_boundary export: the serialized bytes of each assembled file and any diagnostics the guest raised while assembling. Where the assembled group's per-node files sit is not part of this reply — it is a static property of the provider, declared once on its describe() contract and in hand before any node renders. The guest returns each file's serialized bytes; the host writes them verbatim and runs no serializer. Determinism is the guest's responsibility: identical input must produce identical bytes.
export interface AssembleBoundaryOutput {
  // The assembled output files the guest emitted, in emission order. Each names its on-disk path and carries the serialized bytes the host writes verbatim.
  files: RenderedFile[];
  // Diagnostics the guest raised while assembling. Each element is the shared Wasm-plugin diagnostic shape.
  diagnostics?: Diagnostic[];
  // A failure message set when the guest ran but could not complete the operation; absent on success. It is distinct from any diagnostics the output carries: diagnostics report issues found during a run that still produced a result, while error reports that the operation itself did not complete. The host surfaces a present error as a failed plugin invocation.
  error?: string;
  // The descriptive, machine-matchable identity of the condition the failure names — the code the condition is registered under, in the same open set the compiler registers its own halting conditions in, and not a member of the closed host-function error-code catalog a reply envelope's hostfunc_error_code draws from. Set beside the human error message; absent on success, and absent when the guest names no such condition. A guest that halts reports here the identifier of the condition its message names, so a consumer branches on it instead of recovering an identity by reading the message. The host resolves this identifier against the conditions the compiler declares and publishes the resolved condition's own identifiers on the structured diagnostic, so a code that reaches a reader always resolves; an identifier naming no such condition, or one the numbering has retired, halts the build. A guest with no precise condition to name reaches instead for one of the generic plugin-failure conditions the compiler declares for the purpose, and puts the specifics in its own message. This identifier and condition_short_code are reported together, because they name one condition in two forms: a guest that sets one and not the other has named a condition the host cannot resolve, and the host then reports its own generic plugin-failure condition instead while the message still carries the whole failure.
  condition_code?: string;
  // The compact identifier of the same condition — the letter E and four digits, the form a reader quotes, searches for and pastes into a report — set beside the human error message; absent on success, and absent when the guest names no such condition. The host prints it in the bracketed head of the diagnostic it renders for this failure, so a condition a guest raises is quotable exactly as one the compiler raises is. The host resolves the value against the conditions the compiler declares rather than carrying it on trust: a value naming no such condition, a value the numbering has retired, or a spelling the registration does not carry halts the build and quotes the offending value, with the guest's own message still reported. It is reported together with condition_code, for the reason stated there.
  condition_short_code?: string;
}

// The payload a Provider guest receives on its optional carve export: one named output file the pipeline carves into addressable units before a FeatureRecipe step edits some of them. A provider whose output shape the stock YAML codec cannot carve directly (a templated chart, for instance) advertises carve and reassemble so its own output-shape knowledge lives in the guest; a provider that omits the exports borrows the host's stock YAML codec.
export interface CarveInput {
  // The output file's name, so the codec can apply any name-scoped carving rule.
  name: string;
  // The output file's bytes to carve into addressable units. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
  body: string;
  // The indentation width the codec uses when it must synthesize new structured text; carried so the guest's carving matches the render-wide indentation.
  yaml_indent?: number;
}

// The payload a Provider guest returns from its carve export: the ordered addressable units it carved the file into. A structured unit carries a tree (a PATCH target); an opaque unit carries only its media type and bytes.
export interface CarveOutput {
  // The ordered addressable units the guest carved the file into.
  units: unknown[];
}

// The payload a Provider guest receives on its optional reassemble export: the original file plus its carved units and the patched units a pipeline step produced, so the guest splices the changes back into the original bytes surgically. A token absent from the patched set is re-joined from its original bytes verbatim; a patched token has only its addressed byte-spans edited.
export interface ReassembleInput {
  // The output file's name, matching the name the same file was carved under.
  name: string;
  // The original file bytes the reassembly splices the patched units back into. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
  body: string;
  // The units the file was carved into, as carve returned them.
  segs?: unknown[];
  // The units a pipeline step changed, each carrying its token, patched tree, and the ops that produced the change.
  patched?: unknown[];
  // The indentation width the codec uses when an op must synthesize new structured text; carried so the reassembly matches the render-wide indentation.
  yaml_indent?: number;
}

// The payload a Provider guest returns from its reassemble export: the file's bytes with the patched units spliced back in. Reassembly is byte-faithful — every byte the ops did not touch survives verbatim.
export interface ReassembleOutput {
  // The reassembled file bytes the host writes verbatim. Each kit carries them in its own field type — raw where that type is a byte type, base64-encoded where it is a string the guest decodes to recover them — and the generated encoder converts between the field and the form the wire carries bytes in.
  body: string;
}

// The payload a Provider guest receives on its optional name_bound export: one name the host proposes to use as a node's component identity, for the guest to judge against every name it would derive from that identity for its target. The guest answers with a constraint rather than with a name of its own — a derived name travelling back would put the host in the business of composing names for a target it knows nothing about, which is exactly what asking the question removes. A provider whose target bounds or restricts the names it accepts advertises the export; a provider whose target accepts any name omits it and is never asked, and its rendering is unchanged.
export interface NameBoundInput {
  // The name the host proposes as the node's component identity. The guest derives from it, in memory, every name it derives from a component identity and reports whether each one is a name its target accepts. A verdict speaks about the PROPOSAL rather than about the node: the host asks one question wherever it composes an identity, and it does not say which of that node's names this identity will end up being the basis for, so a guest answers as though it were the basis for all of them. That is the conservative direction, because the host only ever shortens on the answer and never lengthens — a name the node will in fact derive from some other carry is therefore judged too strictly rather than too loosely.
  proposed: string;
  // Whether the proposed name is one a person wrote rather than one the compiler composed from authored parts. It is carried so a guest can phrase its reason for the reader who is able to act on it. It does not decide what a refusal does: an authored name is refused and a composed one is shortened, and that decision is the host's.
  authored?: boolean;
}

// One name kind's verdict on a proposed identity: whether the name the guest would derive for that kind is one its target accepts, and — where a shorter identity would be accepted — the greatest length that would be. It carries a constraint and a reason, never a name the guest built.
export interface DerivedNameVerdict {
  // The guest's own name for the kind of name this verdict covers, written in the target's vocabulary rather than the compiler's — a chart installer's release name, a container orchestrator's service name. It reaches a reader verbatim in a refusal, so it is written for somebody who knows the target.
  kind: string;
  // Whether the name the guest would derive for this kind from the proposed identity is one the target accepts.
  usable: boolean;
  // The greatest number of characters a proposed identity may carry for this kind's derived name to be one the target accepts. Present only on a refusal that a shorter identity would satisfy. ABSENT means length is not what the target objected to — either there is no length limit at all, or the objection is one no shortening repairs, such as a character the target's grammar refuses in the position it landed in. Absent is therefore distinct from a bound of zero, which does state a length: that no identity of any length yields an acceptable name of this kind. The host shortens to a present bound and asks again; on an absent bound it stops, because there is nothing left to try.
  bound?: number;
  // Why the target does not accept the derived name, in the target's own terms, for a reader deciding what to write instead. Empty when the verdict is usable.
  reason?: string;
}

// The payload a Provider guest returns from its name_bound export: one verdict per kind of name it would derive from the proposed identity. A proposal is usable when every verdict is; where one is not, the host shortens the proposal to the smallest bound the refusing verdicts carry and asks again, and it stops when a refusing verdict carries no bound. An empty list of verdicts means the guest derives no name from a component identity, which is the same answer as accepting the proposal.
export interface NameBoundOutput {
  // One entry per kind of name the guest derives from a component identity, in the guest's own order. A guest reports every kind it would derive rather than only the kinds that refused, so a reader sees which names were judged and a host reading the entries needs no second call to learn the rest.
  names?: DerivedNameVerdict[];
  // A failure message set when the guest ran but could not complete the operation; absent on success. It is distinct from a refusing verdict: a verdict reports a name the target will not accept, while error reports that the question itself could not be answered. The host surfaces a present error as a failed plugin invocation.
  error?: string;
  // The descriptive, machine-matchable identity of the condition the failure names — the code the condition is registered under, in the same open set the compiler registers its own halting conditions in, and not a member of the closed host-function error-code catalog a reply envelope's hostfunc_error_code draws from. Set beside the human error message; absent on success, and absent when the guest names no such condition. A guest that halts reports here the identifier of the condition its message names, so a consumer branches on it instead of recovering an identity by reading the message. The host resolves this identifier against the conditions the compiler declares and publishes the resolved condition's own identifiers on the structured diagnostic, so a code that reaches a reader always resolves; an identifier naming no such condition, or one the numbering has retired, halts the build. A guest with no precise condition to name reaches instead for one of the generic plugin-failure conditions the compiler declares for the purpose, and puts the specifics in its own message. This identifier and condition_short_code are reported together, because they name one condition in two forms: a guest that sets one and not the other has named a condition the host cannot resolve, and the host then reports its own generic plugin-failure condition instead while the message still carries the whole failure.
  condition_code?: string;
  // The compact identifier of the same condition — the letter E and four digits, the form a reader quotes, searches for and pastes into a report — set beside the human error message; absent on success, and absent when the guest names no such condition. The host prints it in the bracketed head of the diagnostic it renders for this failure, so a condition a guest raises is quotable exactly as one the compiler raises is. The host resolves the value against the conditions the compiler declares rather than carrying it on trust: a value naming no such condition, a value the numbering has retired, or a spelling the registration does not carry halts the build and quotes the offending value, with the guest's own message still reported. It is reported together with condition_code, for the reason stated there.
  condition_short_code?: string;
}

// The payload a Provider guest receives on its optional rendered_name export: the two identities a target derives its own names from, and which input kinds the node's Recipe declares — source the author supplied, a workload the guest synthesizes. The guest answers with the name its target will give the resources it renders for that node: for supplied source, the name the author's own templates render against, such as the release name a chart reads; for a synthesized workload, the name the guest gives the resources it builds, where it derives one rather than writing the node's identity as it is. A guest that derives no such name reports none, which is the honest answer for a target whose resource names a Recipe writes verbatim, and for one whose name is a function of where the files are placed rather than of the node. This export reports a name the guest itself composes and is not the exchange that asks the guest to judge a name the host proposes; those are different questions and each has its own export.
export interface RenderedNameInput {
  // The node's own identity, as authored. It is carried unencoded: a target narrows it through its own alphabet, so encoding it first would put one escape inside another and spell the name differently from the one a recipe author predicts it by.
  node_id: string;
  // The identity a contributor's own source renders against when it is not the node's own — set for a contributor whose identity a target's name alphabet refuses, absent otherwise. A guest resolves the pair the same way every other surface does: this value when it is present, the node id when it is not.
  derived_name_basis?: string;
  // Whether the node's bound Recipe declares source the author supplied, read from the text the author wrote. It is carried, with synthesized, so the question can be asked of any node and answered correctly: a guest reports no name for a node declaring neither, whose output is an artifact set alone, because the resources in such a set are named by the artifacts the author wrote rather than by any name the guest derives.
  sourced?: boolean;
  // Whether the node's bound Recipe declares a workload for the guest to synthesize, read from the text the author wrote, as sourced is. A guest whose target names the resources it synthesizes after a name it derives, rather than after the node's identity as written, reports that name for such a node, so an address a Recipe publishes for one of those resources can be built from the name the resource carries.
  synthesized?: boolean;
}

// The payload a Provider guest returns from its rendered_name export: the name its target gives the resources it renders for the node — from the node's author-supplied source, or from the workload it synthesizes — or no name at all. An absent or empty name is a positive answer rather than a failure — it says this target derives no such name — and the host uses what it was told without reading it, so no knowledge of the target's naming crosses the boundary.
export interface RenderedNameOutput {
  // The name under which the guest renders this node's author-supplied source, or which it gives the resources it synthesizes for the node, already written in the alphabet its target accepts in that position. Empty or absent means the guest derives no such name.
  name?: string;
  // A failure message set when the guest ran but could not complete the operation; absent on success. It is distinct from reporting no name: no name is an answer about the target, while error reports that the question itself could not be answered. The host surfaces a present error as a failed plugin invocation.
  error?: string;
  // The descriptive, machine-matchable identity of the condition the failure names — the code the condition is registered under, in the same open set the compiler registers its own halting conditions in. Set beside the human error message; absent on success, and absent when the guest names no such condition. The host resolves this identifier against the conditions the compiler declares and publishes the resolved condition's own identifiers on the structured diagnostic, so a code that reaches a reader always resolves; an identifier naming no such condition, or one the numbering has retired, halts the build. A guest with no precise condition to name reaches instead for one of the generic plugin-failure conditions the compiler declares for the purpose, and puts the specifics in its own message. This identifier and condition_short_code are reported together, because they name one condition in two forms: a guest that sets one and not the other has named a condition the host cannot resolve, and the host then reports its own generic plugin-failure condition instead while the message still carries the whole failure.
  condition_code?: string;
  // The compact identifier of the same condition — the letter E and four digits, the form a reader quotes, searches for and pastes into a report — set beside the human error message; absent on success, and absent when the guest names no such condition. The host prints it in the bracketed head of the diagnostic it renders for this failure, so a condition a guest raises is quotable exactly as one the compiler raises is. The host resolves the value against the conditions the compiler declares rather than carrying it on trust: a value naming no such condition, a value the numbering has retired, or a spelling the registration does not carry halts the build and quotes the offending value, with the guest's own message still reported. It is reported together with condition_code, for the reason stated there.
  condition_short_code?: string;
}

// One endpoint of a cross-boundary link: the node, the boundary path its rendered output assembles into, and the provider that rendered it. The two endpoints of a link name the consuming and consumed ends of a uses edge whose ends assemble into different dispatch groups.
export interface LinkEndpoint {
  // The endpoint node's absolute id within the topology graph.
  node: string;
  // The endpoint's boundary path — the dispatch group its rendered output assembles into.
  boundary: string;
  // The provider that rendered the endpoint (the bare provider name). Both endpoints of a wired link name the same provider; the host does not route a link whose endpoints name different providers.
  provider: string;
  // The Release the endpoint's rendered output belongs to — the scope its assembled artifacts are named within. The host assembles it from the Release the build resolved and passes it verbatim; it infers no meaning from the value. A provider reads it to scope a cross-reference name to the Release. An absent value is the empty string, which a provider treats as an unscoped name.
  release?: string;
}

// The generalized, domain-agnostic per-edge payload the host assembles for a uses edge whose consuming and consumed ends assemble into different dispatch groups. It carries both endpoints, both endpoints' placement annotations as opaque scalar maps the host does not interpret, the consumed endpoint's provides output, and the socket and inject mapping the edge wires. A provider reads it to produce the provider-native cross-reference wiring the two ends need; the host assembles it and passes the annotation map as opaque scalars, inferring no meaning from any value.
export interface LinkEdge {
  // The consuming endpoint — the source end of the directed uses edge, whose assembled output the consumer-side wiring is injected into.
  source: LinkEndpoint;
  // The consumed endpoint — the target end the uses edge points at, whose assembled output the producer-side wiring publishes.
  target: LinkEndpoint;
  // The consumed (target) endpoint's placement annotations as an opaque scalar map, keyed by annotation name. The host assembles them from the target's resolved annotations and passes them verbatim; it infers no meaning from any value. A provider reads them to decide how to shape a cross-reference (for example whether the two ends share a placement or need a cross-placement reference). Keys serialize in sorted order so the payload is byte-identical across runs of identical input.
  target_annotations?: Record<string, string>;
  // The consuming (source) endpoint's placement annotations as an opaque scalar map, keyed by annotation name. The host assembles them from the source's resolved annotations and passes them verbatim; it infers no meaning from any value. A provider reads them to compare the two ends' placement — for example whether the source and target share a placement or sit in different ones. Keys serialize in sorted order so the payload is byte-identical across runs of identical input.
  source_annotations?: Record<string, string>;
  // The socket alias the uses edge is bound under.
  socket: string;
  // The consumed endpoint's provides output, an author-ordered key set exposing the target's declared outputs. Preserves author order so the payload is byte-identical across runs of identical input.
  provides: Map<string, string>;
  // The consuming endpoint's inject mapping, keyed by delivery mechanism to an author-ordered key set, describing how the consuming end receives the consumed endpoint's output. Preserves author order so the payload is byte-identical across runs of identical input.
  inject: Map<string, Map<string, string>>;
  // The keys of the consumed endpoint's provides output that the consuming endpoint's templates read directly through .context.uses, whether or not the inject mapping also delivers them, in the author order of provides. Each entry is one of the keys provides carries. The list rides on the edge so the producer-side publish and the consumer-side resolve read one list. Absent when the consuming endpoint read no provides key directly, and a provider handed none wires the link exactly as it would if the field did not exist.
  read_provides_keys?: string[];
}

// One per-file structural patch a provider returns as artifact wiring: the output file and the ordered structural operations to apply to it. A later host pass carves the named file, applies the operations, and reassembles it byte-faithfully. The operation shape is the shared pipeline patch-operation vocabulary; it is opaque at this schema layer, so a guest carries each operation verbatim while the host realizes the typed operation its pipeline applies.
export interface LinkPatch {
  // The output file the operations apply to, named as the provider emitted it.
  file: string;
  // The ordered structural operations to apply to the file, in application order.
  ops: unknown[];
}

// The payload a provider receives on its link_publish export: one cross-boundary link whose consumed endpoint's output is referenced across a boundary, and that endpoint's assembled files. The export returns the published identity the consumer resolves against and any producer-side artifact wiring the consumed endpoint's output needs.
export interface LinkPublishInput {
  // The cross-boundary link being published, read from the consumed (target) endpoint's side.
  edge: LinkEdge;
  // The consumed endpoint's assembled files, so the provider can read what that endpoint already declares and check the names it is about to publish against them. Each names its on-disk path and carries the assembled bytes. Absent when the host has no assembled producer output to hand the publish; a provider that needs no document to author its wiring ignores it.
  producer_files?: RenderedFile[];
}

// The payload a provider returns from its link_publish export: the published identity handle the consumer resolves against, and the producer-side artifact wiring to apply to the consumed endpoint's assembled output.
export interface LinkPublishOutput {
  // The published identity the consumed endpoint exposes for the consumer to resolve against, an opaque deterministic-pointer string map keyed by field name (for example an export name, a stack name, a region, a role reference). The values are deterministic pointer strings the compiler pipes and never resolves; the runtime environment resolves them at deploy time. Keys serialize in sorted order so the payload is byte-identical across runs of identical input.
  handle: Record<string, string>;
  // The producer-side artifact wiring, one structural patch per consumed-endpoint output file the publish must edit. Empty when the consumed endpoint's output needs no change for the link.
  patches?: LinkPatch[];
  // A failure message set when the guest ran but could not publish the link; absent on success. The host surfaces a present error as a failed plugin invocation. A publish that cannot proceed — an export name the stack already declares under another entry, say — is reported here rather than only as a crash, so the condition behind it can be named.
  error?: string;
  // The descriptive, machine-matchable identity of the condition the failure names — the code the condition is registered under, in the same open set the compiler registers its own halting conditions in, and not a member of the closed host-function error-code catalog a reply envelope's hostfunc_error_code draws from. Set beside the human error message; absent on success, and absent when the guest names no such condition. A guest that halts reports here the identifier of the condition its message names, so a consumer branches on it instead of recovering an identity by reading the message. The host resolves this identifier against the conditions the compiler declares and publishes the resolved condition's own identifiers on the structured diagnostic, so a code that reaches a reader always resolves; an identifier naming no such condition, or one the numbering has retired, halts the build. A guest with no precise condition to name reaches instead for one of the generic plugin-failure conditions the compiler declares for the purpose, and puts the specifics in its own message. This identifier and condition_short_code are reported together, because they name one condition in two forms: a guest that sets one and not the other has named a condition the host cannot resolve, and the host then reports its own generic plugin-failure condition instead while the message still carries the whole failure.
  condition_code?: string;
  // The compact identifier of the same condition — the letter E and four digits, the form a reader quotes, searches for and pastes into a report — set beside the human error message; absent on success, and absent when the guest names no such condition. The host prints it in the bracketed head of the diagnostic it renders for this failure, so a condition a guest raises is quotable exactly as one the compiler raises is. The host resolves the value against the conditions the compiler declares rather than carrying it on trust: a value naming no such condition, a value the numbering has retired, or a spelling the registration does not carry halts the build and quotes the offending value, with the guest's own message still reported. It is reported together with condition_code, for the reason stated there.
  condition_short_code?: string;
}

// The payload a provider receives on its link_resolve export: one cross-boundary link, the published identity handle its consumed endpoint exposed, and the consuming endpoint's assembled files. The export returns the consumer-side artifact wiring that injects the reference into the consuming endpoint's assembled output.
export interface LinkResolveInput {
  // The cross-boundary link being resolved, read from the consuming (source) endpoint's side.
  edge: LinkEdge;
  // The published identity handle the consumed endpoint's link_publish returned, which the consumer resolves its reference against. Opaque deterministic-pointer strings keyed by field name; the compiler pipes them and never resolves them. Keys serialize in sorted order so the payload is byte-identical across runs of identical input.
  handle: Record<string, string>;
  // The consuming endpoint's assembled files, so the provider can locate the placeholder the host stamped into the consuming output and author its replacement at the placeholder's real path. Each names its on-disk path and carries the assembled bytes. Absent when the host has no assembled consumer output to hand the resolve; a provider that needs no document to author its wiring ignores it.
  consumer_files?: RenderedFile[];
}

// The payload a provider returns from its link_resolve export: the consumer-side artifact wiring to apply to the consuming endpoint's assembled output, injecting the reference to the consumed endpoint's published identity.
export interface LinkResolveOutput {
  // The consumer-side artifact wiring, one structural patch per consuming-endpoint output file the resolve must edit.
  patches: LinkPatch[];
  // A failure message set when the guest ran but could not resolve the link; absent on success. The host surfaces a present error as a failed plugin invocation. A resolve that cannot proceed — a reference the target can only carry as a whole scalar, met inside a larger string — is reported here rather than only as a crash, so the condition behind it can be named.
  error?: string;
  // The descriptive, machine-matchable identity of the condition the failure names — the code the condition is registered under, in the same open set the compiler registers its own halting conditions in, and not a member of the closed host-function error-code catalog a reply envelope's hostfunc_error_code draws from. Set beside the human error message; absent on success, and absent when the guest names no such condition. A guest that halts reports here the identifier of the condition its message names, so a consumer branches on it instead of recovering an identity by reading the message. The host resolves this identifier against the conditions the compiler declares and publishes the resolved condition's own identifiers on the structured diagnostic, so a code that reaches a reader always resolves; an identifier naming no such condition, or one the numbering has retired, halts the build. A guest with no precise condition to name reaches instead for one of the generic plugin-failure conditions the compiler declares for the purpose, and puts the specifics in its own message. This identifier and condition_short_code are reported together, because they name one condition in two forms: a guest that sets one and not the other has named a condition the host cannot resolve, and the host then reports its own generic plugin-failure condition instead while the message still carries the whole failure.
  condition_code?: string;
  // The compact identifier of the same condition — the letter E and four digits, the form a reader quotes, searches for and pastes into a report — set beside the human error message; absent on success, and absent when the guest names no such condition. The host prints it in the bracketed head of the diagnostic it renders for this failure, so a condition a guest raises is quotable exactly as one the compiler raises is. The host resolves the value against the conditions the compiler declares rather than carrying it on trust: a value naming no such condition, a value the numbering has retired, or a spelling the registration does not carry halts the build and quotes the offending value, with the guest's own message still reported. It is reported together with condition_code, for the reason stated there.
  condition_short_code?: string;
}

export function encodeRenderNodeInput(v: RenderNodeInput): string {
  const parts: string[] = [];
  parts.push(`${jstr("node")}:${encodeIRNodeProjection(v.node)}`);
  parts.push(`${jstr("context")}:${encodeOpaque(v.context)}`);
  if (v.source_listing !== undefined && v.source_listing !== null) parts.push(`${jstr("source_listing")}:${encodeSourceListing(v.source_listing)}`);
  if (v.workload_projection !== undefined && v.workload_projection !== null) parts.push(`${jstr("workload_projection")}:${encodeWorkloadProjection(v.workload_projection)}`);
  if (v.artifacts_projection !== undefined && v.artifacts_projection !== null) parts.push(`${jstr("artifacts_projection")}:${encodeArtifactsProjection(v.artifacts_projection)}`);
  if (v.omits !== undefined && v.omits.length > 0) parts.push(`${jstr("omits")}:${`[${v.omits!.map((e0) => encodeOmitEntry(e0)).join(",")}]`}`);
  return `{${parts.join(",")}}`;
}

export function decodeRenderNodeInput(data: string): RenderNodeInput {
  const o: any = {};
  readJSONMembers(data, (k, raw) => {
    switch (k) {
      case "node": o["node"] = decodeIRNodeProjection(raw); break;
      case "context": o["context"] = JSON.parse(raw); break;
      case "source_listing": o["source_listing"] = JSON.parse(raw); break;
      case "workload_projection": o["workload_projection"] = (raw === "null" ? null : decodeWorkloadProjection(raw)); break;
      case "artifacts_projection": o["artifacts_projection"] = JSON.parse(raw); break;
      case "omits": o["omits"] = JSON.parse(raw); break;
    }
  });
  return o as RenderNodeInput;
}

export function encodeIRNodeProjection(v: IRNodeProjection): string {
  const parts: string[] = [];
  parts.push(`${jstr("id")}:${jstr(v.id)}`);
  parts.push(`${jstr("type")}:${jstr(v.type)}`);
  parts.push(`${jstr("resolved_recipe")}:${jstr(v.resolved_recipe)}`);
  if (v.values !== undefined && v.values.size > 0) parts.push(`${jstr("values")}:${writeOrderedObject(v.values!, (v0) => encodeOpaque(v0))}`);
  if (v.features !== undefined && v.features.size > 0) parts.push(`${jstr("features")}:${writeOrderedObject(v.features!, (v0) => encodeOpaque(v0))}`);
  if (v.sensitive_rendered_keys !== undefined && Object.keys(v.sensitive_rendered_keys).length > 0) parts.push(`${jstr("sensitive_rendered_keys")}:${`{${Object.keys(v.sensitive_rendered_keys!).sort().map((k0) => `${jstr(k0)}:${jstr(v.sensitive_rendered_keys![k0])}`).join(",")}}`}`);
  if (v.sensitive_values !== undefined && v.sensitive_values !== false) parts.push(`${jstr("sensitive_values")}:${String(v.sensitive_values)}`);
  if (v.values_mapped !== undefined && v.values_mapped !== false) parts.push(`${jstr("values_mapped")}:${String(v.values_mapped)}`);
  if (v.uses !== undefined && v.uses.size > 0) parts.push(`${jstr("uses")}:${writeOrderedObject(v.uses!, (v0) => `[${v0!.map((e1) => jstr(e1)).join(",")}]`)}`);
  if (v.boundary_path !== undefined && v.boundary_path !== "") parts.push(`${jstr("boundary_path")}:${jstr(v.boundary_path)}`);
  if (v.sync_wave !== undefined && v.sync_wave !== 0) parts.push(`${jstr("sync_wave")}:${String(v.sync_wave)}`);
  if (v.recipe_name !== undefined && v.recipe_name !== "") parts.push(`${jstr("recipe_name")}:${jstr(v.recipe_name)}`);
  if (v.recipe_version !== undefined && v.recipe_version !== "") parts.push(`${jstr("recipe_version")}:${jstr(v.recipe_version)}`);
  if (v.label_component_id !== undefined && v.label_component_id !== "") parts.push(`${jstr("label_component_id")}:${jstr(v.label_component_id)}`);
  if (v.derived_name_basis !== undefined && v.derived_name_basis !== "") parts.push(`${jstr("derived_name_basis")}:${jstr(v.derived_name_basis)}`);
  if (v.output_labels !== undefined && Object.keys(v.output_labels).length > 0) parts.push(`${jstr("output_labels")}:${`{${Object.keys(v.output_labels!).sort().map((k0) => `${jstr(k0)}:${jstr(v.output_labels![k0])}`).join(",")}}`}`);
  parts.push(`${jstr("provenance")}:${encodeNodeProvenance(v.provenance)}`);
  return `{${parts.join(",")}}`;
}

export function decodeIRNodeProjection(data: string): IRNodeProjection {
  const o: any = {};
  readJSONMembers(data, (k, raw) => {
    switch (k) {
      case "id": o["id"] = JSON.parse(raw); break;
      case "type": o["type"] = JSON.parse(raw); break;
      case "resolved_recipe": o["resolved_recipe"] = JSON.parse(raw); break;
      case "values": o["values"] = readOrderedObject(raw, (r0) => JSON.parse(r0)); break;
      case "features": o["features"] = readOrderedObject(raw, (r0) => JSON.parse(r0)); break;
      case "sensitive_rendered_keys": o["sensitive_rendered_keys"] = JSON.parse(raw); break;
      case "sensitive_values": o["sensitive_values"] = JSON.parse(raw); break;
      case "values_mapped": o["values_mapped"] = JSON.parse(raw); break;
      case "uses": o["uses"] = readOrderedObject(raw, (r0) => JSON.parse(r0)); break;
      case "boundary_path": o["boundary_path"] = JSON.parse(raw); break;
      case "sync_wave": o["sync_wave"] = JSON.parse(raw); break;
      case "recipe_name": o["recipe_name"] = JSON.parse(raw); break;
      case "recipe_version": o["recipe_version"] = JSON.parse(raw); break;
      case "label_component_id": o["label_component_id"] = JSON.parse(raw); break;
      case "derived_name_basis": o["derived_name_basis"] = JSON.parse(raw); break;
      case "output_labels": o["output_labels"] = JSON.parse(raw); break;
      case "provenance": o["provenance"] = JSON.parse(raw); break;
    }
  });
  return o as IRNodeProjection;
}

export function encodeNodeProvenance(v: NodeProvenance): string {
  const parts: string[] = [];
  if (v.compiler_version !== undefined && v.compiler_version !== "") parts.push(`${jstr("compiler_version")}:${jstr(v.compiler_version)}`);
  if (v.aggregate_name !== undefined && v.aggregate_name !== "") parts.push(`${jstr("aggregate_name")}:${jstr(v.aggregate_name)}`);
  if (v.environment !== undefined && v.environment !== "") parts.push(`${jstr("environment")}:${jstr(v.environment)}`);
  if (v.provider_name !== undefined && v.provider_name !== "") parts.push(`${jstr("provider_name")}:${jstr(v.provider_name)}`);
  if (v.provider_version !== undefined && v.provider_version !== "") parts.push(`${jstr("provider_version")}:${jstr(v.provider_version)}`);
  return `{${parts.join(",")}}`;
}

